 void marketCard(){LinearLayout c=card();c.addView(t("PİYASA ÖZETİ",12,ACCENT));marketPrice=t("BTC / USD     —     veri bekleniyor",18,Color.WHITE);marketPrice.setTypeface(null,Typeface.BOLD);oneLine(marketPrice);c.addView(marketPrice);marketAsset=spin(new String[]{"BTC-USD","ETH-USD","SOL-USD","DOGE-USD","LTC-USD","AVAX-USD"},0);c.addView(marketAsset);marketTimeframe=spin(new String[]{"1m","5m","15m","1h","6h","1D"},0);c.addView(marketTimeframe);marketAsset.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int i,long id){if(chartView!=null){chartView.loadDrawing(getPreferences(MODE_PRIVATE),marketAsset.getSelectedItem().toString());chartSnapshot();}}});marketTimeframe.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int i,long id){if(chartView!=null)chartSnapshot();}});chartView=new ChartView(this);chartView.accent=ACCENT;chartView.loadDrawing(getPreferences(MODE_PRIVATE),marketAsset.getSelectedItem().toString());chartView.setContentDescription("BTC USD mum grafiği; veri bekleniyor");c.addView(chartView,new LinearLayout.LayoutParams(-1,420));LinearLayout controls=row();Button zoomIn=new Button(this);zoomIn.setText("＋ Yakınlaştır");zoomIn.setAllCaps(false);zoomIn.setOnClickListener(v->chartView.zoom(-1));controls.addView(zoomIn,new LinearLayout.LayoutParams(0,54,1));Button zoomOut=new Button(this);zoomOut.setText("－ Uzaklaştır");zoomOut.setAllCaps(false);zoomOut.setOnClickListener(v->chartView.zoom(1));controls.addView(zoomOut,new LinearLayout.LayoutParams(0,54,1));c.addView(controls);LinearLayout replayControls=row();Button replayStart=new Button(this);replayStart.setText("▶ Replay başlat");replayStart.setAllCaps(false);replayStart.setOnClickListener(v->{if(chartView.startReplay())replayStart.setText("↺ Baştan");else android.widget.Toast.makeText(this,"Replay için mum verisi gerekli",android.widget.Toast.LENGTH_SHORT).show();});replayControls.addView(replayStart,new LinearLayout.LayoutParams(0,54,1));Button replayStep=new Button(this);replayStep.setText("Sonraki mum ›");replayStep.setAllCaps(false);replayStep.setOnClickListener(v->{if(!chartView.stepReplay())android.widget.Toast.makeText(this,"Replay başlatın veya son muma ulaşıldı",android.widget.Toast.LENGTH_SHORT).show();});replayControls.addView(replayStep,new LinearLayout.LayoutParams(0,54,1));Button replayExit=new Button(this);replayExit.setText("Bitir");replayExit.setAllCaps(false);replayExit.setOnClickListener(v->{chartView.stopReplay();replayStart.setText("▶ Replay başlat");});replayControls.addView(replayExit,new LinearLayout.LayoutParams(0,54,1));c.addView(replayControls);LinearLayout drawingControls=row();Button lineStart=new Button(this);lineStart.setText("Çizgi başlangıcı");lineStart.setAllCaps(false);lineStart.setOnClickListener(v->{if(chartView.markDrawingStart())android.widget.Toast.makeText(this,"Başlangıç kaydedildi; bitiş için dokunun",android.widget.Toast.LENGTH_SHORT).show();else android.widget.Toast.makeText(this,"Önce mum verisi yüklenmeli",android.widget.Toast.LENGTH_SHORT).show();});drawingControls.addView(lineStart,new LinearLayout.LayoutParams(0,54,1));Button lineEnd=new Button(this);lineEnd.setText("Çizgiyi kaydet");lineEnd.setAllCaps(false);lineEnd.setOnClickListener(v->{if(chartView.saveDrawing(getPreferences(MODE_PRIVATE),marketAsset.getSelectedItem().toString()))android.widget.Toast.makeText(this,"Çizim kaydedildi",android.widget.Toast.LENGTH_SHORT).show();else android.widget.Toast.makeText(this,"Grafikte başlangıç ve bitiş seçin",android.widget.Toast.LENGTH_SHORT).show();});drawingControls.addView(lineEnd,new LinearLayout.LayoutParams(0,54,1));Button lineDelete=new Button(this);lineDelete.setText("Çizimi sil");lineDelete.setAllCaps(false);lineDelete.setOnClickListener(v->chartView.deleteDrawing(getPreferences(MODE_PRIVATE),marketAsset.getSelectedItem().toString()));drawingControls.addView(lineDelete,new LinearLayout.LayoutParams(0,54,1));c.addView(drawingControls);c.addView(t("Çizim: başlangıca dokun → bitişe dokun → kaydet. Sembol başına son çizgi saklanır.",12,MUTED));LinearLayout paperControls=row();Button paperBuy=new Button(this);paperBuy.setText("DEMO AL");paperBuy.setAllCaps(false);paperBuy.setOnClickListener(v->placeChartPaperOrder(FinancePaperOrders.Side.BUY));paperControls.addView(paperBuy,new LinearLayout.LayoutParams(0,56,1));Button paperSell=new Button(this);paperSell.setText("DEMO SAT");paperSell.setAllCaps(false);paperSell.setOnClickListener(v->placeChartPaperOrder(FinancePaperOrders.Side.SELL));paperControls.addView(paperSell,new LinearLayout.LayoutParams(0,56,1));c.addView(paperControls);c.addView(t("Demo emirleri yalnızca cihazda değerlendirilir. Gerçek emir gönderilmez.",12,MUTED));c.addView(t("Replay: geçmiş mumları adım adım gösterir; canlı emir oluşturmaz.",12,MUTED));c.addView(t("Mum grafik • hacim • salt okunur veri",12,MUTED));marketProviders=t("Piyasa verisi: Coinbase + Kraken + Bybit hazırlanıyor",12,MUTED);c.addView(marketProviders);root.addView(c,mp(12));}
 void placeChartPaperOrder(FinancePaperOrders.Side side){
  if(chartView==null||marketAsset==null||chartView.candles.isEmpty()){
   new AlertDialog.Builder(this).setTitle("DEMO").setMessage("Geçerli mum fiyatı bulunamadı; emir oluşturulmadı.").setPositiveButton("Tamam",null).show();return;
  }
  float last=chartView.candles.get(chartView.candles.size()-1)[3];
  if(!Float.isFinite(last)||last<=0)return;
  final String symbol=marketAsset.getSelectedItem().toString();
  final EditText qty=new EditText(this);qty.setInputType(8194);qty.setText("0.01");
  new AlertDialog.Builder(this).setTitle("DEMO "+(side==FinancePaperOrders.Side.BUY?"AL":"SAT")+" • "+symbol)
   .setMessage("Son mum kapanışı: "+String.format(Locale.ROOT,"%.4f",last)+"\\nSadece simülasyon; fiyat ve gerçekleşme garantisi yok.\\nMiktar:")
   .setView(qty).setNegativeButton("Vazgeç",null).setPositiveButton("Demo emrini değerlendir",(dialog,which)->{
    double quantity;
    try{quantity=Double.parseDouble(qty.getText().toString().trim());}catch(Exception ex){quantity=Double.NaN;}
    FinancePaperOrders.Order order=new FinancePaperOrders.Order(symbol,side,FinancePaperOrders.Type.MARKET,quantity,0,"chart_"+SystemClock.uptimeMillis());
    FinancePaperOrders.Result result=FinancePaperOrders.evaluate(order,last);
    String outcome=result.status==FinancePaperOrders.Status.FILLED
      ?"DEMO gerçekleşti • "+String.format(Locale.ROOT,"%.4f",result.fillPrice)
      :"DEMO reddedildi • "+result.reason;
    new AlertDialog.Builder(this).setTitle("DEMO SONUCU").setMessage(outcome+"\\nBu işlem gerçek portföyünüzü değiştirmez.").setPositiveButton("Tamam",null).show();
   }).show();
 }
  void nav(){LinearLayout r=row();String[] items={"Ana Sayfa","Piyasalar","Trading","Portföy","Cüzdan","Profil"};for(String item:items){TextView n=t(item,10,MUTED);n.setGravity(Gravity.CENTER);oneLine(n);n.setBackground(pill(Color.rgb(8,11,18),item.equals("Trading")?ACCENT:Color.rgb(32,40,56)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,52,1);p.setMargins(2,0,2,0);r.addView(n,p);n.setOnClickListener(v->openFinanceScreen(item));}root.addView(r,mp(20));}
 void openFinanceScreen(String name){
  if("Trading".equals(name)){build();return;}
  final int white=Color.WHITE;ScrollView scroll=new ScrollView(this);LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(26,24,26,26);body.setBackgroundColor(BG);scroll.addView(body);
  TextView heading=t(name.toUpperCase(Locale.ROOT),24,white);heading.setTypeface(null,Typeface.BOLD);heading.setLetterSpacing(.06f);body.addView(heading);body.addView(t("MARS-X FINANCE  /  DEMO WORKSPACE",10,ACCENT));
  if("Ana Sayfa".equals(name)){financeHero(body,"TOPLAM PORTFÖY","—","Canlı bakiye bağlantısı bekleniyor");financeSection(body,"PİYASA GENEL BAKIŞ");financeLine(body,"BTC / USD","Veri bekleniyor");financeLine(body,"ETH / USD","Veri bekleniyor");financeLine(body,"SOL / USD","Veri bekleniyor");financeSection(body,"HIZLI İŞLEMLER");financeAction(body,"Piyasaları Gör",()->openFinanceScreen("Piyasalar"));financeAction(body,"Cüzdanı Aç",()->openFinanceScreen("Cüzdan"));}
  else if("Piyasalar".equals(name)){financeSection(body,"İZLEME LİSTESİ");for(String coin:new String[]{"BTC / USD","ETH / USD","SOL / USD","BNB / USD","EUR / USD","XAU / USD"})financeLine(body,coin,"—");financeSection(body,"VERİ KALİTESİ");financeLine(body,"Durum","Bağlantı bekleniyor");financeLine(body,"Veri kaynağı","Salt okunur");}
  else if("Portföy".equals(name)){financeHero(body,"PORTFÖY DEĞERİ","—","Doğrulanmış bakiye bulunmuyor");financeSection(body,"VARLIK DAĞILIMI");financeLine(body,"Spot Varlıklar","—");financeLine(body,"Açık Pozisyonlar","—");financeLine(body,"Günlük Kâr / Zarar","—");financeSection(body,"PERFORMANS");financeLine(body,"Gerçekleşmiş Kâr / Zarar","—");financeLine(body,"Geçmiş İşlemler","Henüz veri yok");}
  else if("Cüzdan".equals(name)){financeHero(body,"CÜZDAN BAKİYESİ","—","Bakiye sağlayıcısı bağlı değil");financeSection(body,"CÜZDAN İŞLEMLERİ");financeAction(body,"Para Yatır",()->financePreview("Para yatırma"));financeAction(body,"Para Çek",()->financePreview("Para çekme"));financeAction(body,"Transfer",()->financePreview("Transfer"));financeSection(body,"VARLIKLAR");for(String coin:new String[]{"BTC","ETH","USDT","SOL"})financeLine(body,coin,"—");}
  else if("Profil".equals(name)){financeSection(body,"HESAP");financeLine(body,"Oturum","Demo");financeLine(body,"Kimlik Doğrulama","Bağlı değil");financeSection(body,"GÜVENLİK");financeLine(body,"İki Aşamalı Doğrulama","Yapılandırılmadı");financeLine(body,"Cihazlar","—");financeSection(body,"TERCİHLER");financeAction(body,"Görünüm ve Tema",()->financeThemeDialog());financeAction(body,"Bildirimler",()->financePreview("Bildirimler"));financeAction(body,"İşlem Geçmişi",()->financePreview("İşlem geçmişi"));financeAction(body,"Fiyat Alarmları",()->financePreview("Fiyat alarmları"));}
  if("Ana Sayfa".equals(name)||"Piyasalar".equals(name)){final LinearLayout target=body;financeAction(body,"↻ Canlı piyasa fiyatlarını yenile",()->loadPublicPrices(target));loadPublicPrices(body);}
  financeAction(body,"← Ana ekrana dön",()->build());
  LinearLayout screen=new LinearLayout(this);screen.setOrientation(LinearLayout.VERTICAL);screen.setBackgroundColor(BG);screen.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  setContentView(screen);screen.setAlpha(0f);screen.animate().alpha(1f).setDuration(220).start();
 }
 void loadPublicPrices(LinearLayout body){TextView state=t("Coinbase • canlı fiyatlar yükleniyor…",13,MUTED);body.addView(state,mp(8));new Thread(()->{String[] assets={"BTC-USD","ETH-USD","SOL-USD","DOGE-USD","LTC-USD"};ArrayList<String> lines=new ArrayList<>();for(String symbol:assets){try{HttpURLConnection c=(HttpURLConnection)new URL("https://api.exchange.coinbase.com/products/"+symbol+"/ticker").openConnection();c.setConnectTimeout(5000);c.setReadTimeout(5000);c.setRequestProperty("Accept","application/json");try{if(c.getResponseCode()!=200)throw new IOException("HTTP "+c.getResponseCode());JSONObject j=new JSONObject(read(c.getInputStream()));double price=j.optDouble("price",Double.NaN);if(Double.isFinite(price)&&price>0)lines.add(symbol+"   $"+String.format(Locale.ROOT,"%,.2f",price));}finally{c.disconnect();}}catch(Exception ignored){}}runOnUiThread(()->{if(!body.isAttachedToWindow())return;state.setText(lines.isEmpty()?"Canlı fiyat bağlantısı başarısız • demo fiyatı gösterilmiyor":"Coinbase Exchange • doğrulanmış salt-okunur fiyatlar");for(String line:lines)financeLine(body,line.split("   ")[0],line.substring(line.indexOf("   ")+3));});}).start();}
 void financeHero(LinearLayout parent,String label,String value,String note){LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(24,22,24,22);panel.setBackground(panel(RAISED,22,ACCENT));TextView title=t(label,11,ACCENT);title.setLetterSpacing(.08f);panel.addView(title);TextView big=t(value,35,Color.WHITE);big.setTypeface(null,Typeface.BOLD);panel.addView(big);panel.addView(t(note,12,MUTED));MiniGraph g=new MiniGraph(this);g.accent=ACCENT;panel.addView(g,new LinearLayout.LayoutParams(-1,120));parent.addView(panel,mp(20));}
